exercise.solution:
model LabL09Post {
  id       Int    @id @default(autoincrement())
  name     String
  children LabL09Comment[]
  @@map("lab_l09_posts")
}

model LabL09Comment {
  id    Int    @id @default(autoincrement())
  title String
  postId Int @map("post_id")
  post LabL09Post @relation(fields: [postId], references: [id], onDelete: Cascade)
  @@map("lab_l09_comments")
}

